import time


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if isinstance(capacity, bool) or capacity <= 0 or not isinstance(capacity, int):
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self.clock = clock
        self.items = OrderedDict()

    def put(self, key, value, ttl):
        if ttl <= 0:
            # Non-positive TTL: remove the key if it exists, do not insert
            if key in self.items:
                del self.items[key]
            return

        self.items[key] = (value, self.clock() + ttl)
        # Evict if capacity exceeded
        if len(self.items) > self.capacity:
            self.items.popitem()

    def get(self, key, default=None):
        item = self.items.get(key)
        if item is None:
            return default

        value, expires = item
        if self.clock() >= expires:
            # Entry is expired, remove it
            del self.items[key]
            return default

        # Refresh recency on successful get
        self.items.move_to_end(key)
        return value
