            if key in self.items:
                del self.items[key]
            return

        self.items[key] = (value, self.clock() + ttl)
        # Evict if capacity exceeded, but skip expired items
        if len(self.items) > self.capacity:
            # Find the least recently used non-expired item
            while True:
                key, (value, expires) = self.items.popitem()
                if self.clock() < expires:
                    # This item is not expired, evict it
                    break

    def get(self, key, default=None):
        item = self.items.get(key)
        if item is None:
            return default

        value, expires = item
        if self.clock() >= expires:
            # Entry is expired, remove it
            del self.items[key]
            return default

        # Refresh recency on successful get
        self.items.move_to_end(key)
        return value
